require_once __DIR__.'/includes/auth.php';require_login();$pdo=db();$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$current=$_POST['current_password']??'';$password=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';$stmt=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$stmt->execute([current_user()['id']]);$hash=$stmt->fetchColumn();if(!password_verify($current,$hash))$error='Current password is incorrect.';elseif(strlen($password)<8||$password!==$confirm)$error='Use matching passwords with at least 8 characters.';else{$old=$pdo->prepare('SELECT password_hash FROM password_history WHERE user_id=? ORDER BY created_at DESC LIMIT 5');$old->execute([current_user()['id']]);foreach($old as $row)if(password_verify($password,$row['password_hash']))$error='You cannot reuse one of your five recent passwords.';if(!$error){$pdo->prepare('INSERT INTO password_history (user_id,password_hash) VALUES (?,?)')->execute([current_user()['id'],$hash]);$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),current_user()['id']]);audit_action('password_changed','users',(int)current_user()['id']);flash('success','Your password has been changed.');redirect('change_password.php');}}}
$pageTitle='Change password';$activePage='change_password';require __DIR__.'/partials/header.php';?><section class="section-heading"><div><div class="eyebrow">Account security</div><h1>Change password</h1><p>Use a unique password. Your five most recent passwords cannot be reused.</p></div></section><section class="panel form-panel"><form method="post" class="form-grid single-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><?php if($error): ?><div class="flash error wide"><?= h($error) ?></div><?php endif; ?><label>Current password<input type="password" name="current_password" required autocomplete="current-password"></label><label>New password<input type="password" name="password" minlength="8" required autocomplete="new-password"></label><label>Confirm new password<input type="password" name="confirm_password" minlength="8" required autocomplete="new-password"></label><div class="form-actions"><button class="primary-button">Update password</button></div></form></section><?php require __DIR__.'/partials/footer.php'; ?>
